using sv_aaa1c9b3b8324f5e95ddf973844f9916.Client.Models;
using sv_aaa1c9b3b8324f5e95ddf973844f9916.Client.Services;

namespace sv_aaa1c9b3b8324f5e95ddf973844f9916.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 2, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 25, 9, 0, 0, TimeSpan.Zero), "Package picked up", "New York, NY"),
                new(new DateTimeOffset(2026, 6, 26, 14, 30, 0, TimeSpan.Zero), "Departed facility", "New York, NY"),
                new(new DateTimeOffset(2026, 6, 27, 8, 15, 0, TimeSpan.Zero), "Arrived at hub", "Chicago, IL"),
            }),
        ["TRK-002"] = new Shipment(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 26, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 23, 10, 0, 0, TimeSpan.Zero), "Package picked up", "Seattle, WA"),
                new(new DateTimeOffset(2026, 6, 24, 6, 0, 0, TimeSpan.Zero), "In transit", "Portland, OR"),
                new(new DateTimeOffset(2026, 6, 25, 11, 0, 0, TimeSpan.Zero), "Out for delivery", "San Francisco, CA"),
                new(new DateTimeOffset(2026, 6, 25, 14, 22, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            }),
        ["TRK-003"] = new Shipment(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 5, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 6, 27, 16, 45, 0, TimeSpan.Zero), "Label created", "Dallas, TX"),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using sv_aaa1c9b3b8324f5e95ddf973844f9916.Client.Services;

namespace sv_aaa1c9b3b8324f5e95ddf973844f9916.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        app.MapGet("api/shipments/{trackingNumber}", async (string trackingNumber, IShipmentService service, CancellationToken ct) =>
        {
            var shipment = await service.GetShipmentAsync(trackingNumber, ct);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });
    }
}

